public class LanternTraveler {

    private volatile boolean asleep = false;

    public void countSomeSheep() {
        System.out.println("Tallying a lantern...");
        try {
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
        System.out.println("The traveler has fallen asleep.");
    }

    public static void main(String[] args) {
        LanternTraveler simulation = new LanternTraveler();

        Thread travelerThread = new Thread(simulation::tryToSleep);
        travelerThread.start();

        try {
            Thread.sleep(2500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        simulation.asleep = true;

        try {
            travelerThread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TravelerSimulation {

    static class Traveler implements Runnable {
        private volatile boolean asleep = false;

        public void setAsleep(boolean asleep) {
            this.asleep = asleep;
        }

        private void countSomeSheep() {
            System.out.println("Tallying a lantern...");
            try {
                Thread.sleep(500);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        public void tryToSleep() {
            while (!asleep) {
                countSomeSheep();
            }
            System.out.println("The traveler has fallen asleep.");
        }

        public void run() {
            tryToSleep();
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Traveler traveler = new Traveler();

        executor.execute(traveler);

        executor.execute(() -> {
            try {
                Thread.sleep(2000);
                traveler.setAsleep(true);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

