import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StellarSprites {

    private final Set<String> spriteTags;

    public StellarSprites() {
        Set<String> mutableTags = new HashSet<>();
        mutableTags.add("Flare");
        mutableTags.add("Glint");
        mutableTags.add("Spark");
        this.spriteTags = Collections.unmodifiableSet(mutableTags);
    }

    public boolean isSprite(String tag) {
        return spriteTags.contains(tag);
    }

    public String getSpriteList() {
        return spriteTags.toString();
    }

    public static void main(String[] args) {
        StellarSprites stellarSprites = new StellarSprites();

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        executorService.submit(() -> {
            System.out.println("Current Sprites Collection: " + stellarSprites.getSpriteList());
        });

        executorService.submit(() -> {
            String[] candidates = {"Flare", "Shadow", "Glint", "Mist", "Spark"};
            for (String candidate : candidates) {
                boolean isMember = stellarSprites.isSprite(candidate);
                System.out.println("Is " + candidate + " a Stellar Sprite? " + isMember);
            }
        });

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
