import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingTrackerDemo {

    public static void main(String[] args) {
        // 1. Setup initial data
        Map<String, Point> initialPoints = new HashMap<>();
        initialPoints.put("Truck-1", new Point(0, 0));
        initialPoints.put("Truck-2", new Point(10, 10));
        initialPoints.put("Truck-3", new Point(20, 20));

        // 2. Initialize Tracker
        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPoints);

        System.out.println("System started. Initial state: " + tracker.getLocations());

        // 3. Create Executor with 2 threads (Total threads = 1 Main + 2 Workers = 3)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Task 1: The Updater (Writer)
        // This thread moves Truck-1 incrementally and tries to update a non-existent truck.
        Runnable writerTask = () -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    int newX = i * 5;
                    int newY = i * 5;

                    // Update existing gadget
                    tracker.setLocation("Truck-1", newX, newY);
                    System.out.println("[Writer] Moved Truck-1 to (" + newX + ", " + newY + ")");

                    // Attempt to update non-existent gadget (should fail silently or do nothing based on map logic)
                    tracker.setLocation("Ghost-Truck", 99, 99);

                    // Simulate work
                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Task 2: The Monitor (Reader)
        // This thread demonstrates the difference between the Snapshot and the Live View.
        Runnable readerTask = () -> {
            try {
                // Let the writer start
                Thread.sleep(150);

                // 1. Take a static snapshot
                Map<String, Point> snapshot = tracker.getLocationsSnapshot();
                System.out.println("[Reader] Taken SNAPSHOT: " + snapshot);

                // Sleep to allow Writer to make more changes
                Thread.sleep(200);

                // 2. Check the Live View
                Map<String, Point> liveView = tracker.getLocations();
                System.out.println("[Reader] checking LIVE VIEW: " + liveView);

                // 3. Verify snapshot hasn't changed even though Writer moved Truck-1
                System.out.println("[Reader] checking SNAPSHOT again (should be old data): " + snapshot);

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // 4. Execute tasks
        executor.submit(writerTask);
        executor.submit(readerTask);

        // 5. Shutdown and Cleanup
        executor.shutdown();
        try {
            // Wait for tasks to finish
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("Final System State: " + tracker.getLocations());
    }
}

/**
 * Immutable Point class to ensure thread safety when publishing position data.
 * Once a Point is put into the map, it cannot be changed, only replaced.
 */
class Point {
    public final int x;
    public final int y;

    public Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

/**
 * Thread-safe tracker using delegation to ConcurrentHashMap.
 */
class DelegatingDeviceTracker {
    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMap;

    public DelegatingDeviceTracker(Map<String, Point> points) {
        // Create a ConcurrentHashMap initialized with the provided points
        this.locations = new ConcurrentHashMap<>(points);
        // Prepare the live view
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

