// The Thread-Safe Tracker using Delegation
class DelegatingParcelTracker {
    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMap;

    public DelegatingParcelTracker(Map<String, Point> points) {
        // Initialize ConcurrentHashMap with the data.
        // ConcurrentHashMap handles the thread safety of the map structure itself.
        this.locations = new ConcurrentHashMap<>(points);

        // Create a "live" unmodifiable view wrapper around the concurrent map.
        // This is initialized once and returned by getLocations().
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    /**
     * Returns a live, unmodifiable view of the package locations.
     * Changes made to the underlying tracker are immediately visible here.
     */
    public Map<String, Point> getLocations() {
        return unmodifiableMap;
    }

    /**
     * Returns a static snapshot of the locations at the moment of the call.
     * Subsequent changes to the tracker are NOT visible in this map.
     */
    public Map<String, Point> getLocationsSnapshot() {
        // We create a shallow copy of the map structure.
        // Since Point is immutable, a shallow copy is sufficient for thread safety here.
        // The iterator of ConcurrentHashMap (used by HashMap constructor) is weakly consistent.
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    /**
     * Returns the position of a specific package.
     */
    public Point getLocation(String id) {
        return locations.get(id);
    }

    /**
     * Assigns the position of a package.
     * Only updates if the package ID already exists in the map.
     */
    public void setLocation(String id, int x, int y) {
        // replace(key, value) only performs the action if the key is currently mapped to some value.
        // It is atomic. If the key doesn't exist, it does nothing and returns null.
        if (locations.replace(id, new Point(x, y)) == null) {
            // Logic could be added here to handle the case where ID didn't exist,
            // but requirements state we simply ensure it only succeeds if ID exists.
        }
    }
}

