        // Create a defensive copy into the ConcurrentHashMap
        this.locations = new ConcurrentHashMap<>(points);
        // Initialize the live view wrapper once
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    /**
     * Returns the live, unmodifiable view of the locations.
     * Changes in the underlying map are reflected here immediately.
     */
    public Map<String, Point> getLocations() {
        return unmodifiableMap;
    }

