     * Returns a static snapshot of the locations at the moment of calling.
     * Changes to the underlying map after this call are NOT reflected here.
     */
    public Map<String, Point> getLocationsSnapshot() {
        // Construct a new HashMap to copy data, then wrap it
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

