     */
    public Point getLocation(String id) {
        return locations.get(id);
    }

    /**
     * Assigns a new position to a package.
     * Updates only if the package ID already exists in the map.
     */
    public void setLocation(String id, Point location) {
        // replace(key, value) returns null if the key was not found,
        // or the previous value if it was found.
        // ConcurrentHashMap does not allow null keys or values.
        if (locations.replace(id, location) == null) {
            throw new IllegalArgumentException("No such package ID: " + id);
        }
    }
