    public DelegatingRobotTracker(Map<String, Point> points) {
        this.locations = new ConcurrentHashMap<>(points);
    }

    // Returns an unmodifiable view of the live map
    // This view will reflect changes made to the underlying map
    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(locations);
    }

    // Returns a static snapshot of the current state
    // This map will NOT reflect subsequent changes
    public Map<String, Point> getSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

