    // Returns true if updated, false if robot ID not found
    public boolean setLocation(String id, int x, int y) {
        Point newLocation = new Point(x, y);
        // replace returns null if the key was not found, otherwise returns the old value
        // Since ConcurrentHashMap does not allow null values, a null return strictly means key missing
        return locations.replace(id, newLocation) != null;
    }

