import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingRobotTracker {

    // The underlying concurrent map manages thread safety via delegation
    private final ConcurrentMap<String, Point> locations;

    // Initialize with a map of robot IDs to their initial coordinates
    public DelegatingRobotTracker(Map<String, Point> points) {
        // We copy the input map into a ConcurrentHashMap to ensure we own the data structure
        this.locations = new ConcurrentHashMap<>(points);
    }

    // Returns a live view of the map. Changes to the underlying map are reflected here.
    // The returned map is unmodifiable to prevent external code from corrupting state.
    public Map<String, Point> getLocationsLive() {
        return Collections.unmodifiableMap(locations);
    }

    // Returns a static snapshot of the map at the moment of the call.
    // Changes to the underlying map after this call are NOT reflected here.
    public Map<String, Point> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    // specific robot coordinate check
    public Point getLocation(String id) {
        return locations.get(id);
    }

    // Modifies coordinates only if the robot ID already exists.
    // Uses ConcurrentHashMap.replace() which is atomic and returns null if key missing.
    public void setLocation(String id, int x, int y) {
        if (locations.replace(id, new Point(x, y)) == null) {
            System.out.println("Failed to update: Robot ID " + id + " not found.");
        }
    }

    // Entry point
    public static void main(String[] args) {
        // 1. Setup Initial Data
        Map<String, Point> initialPoints = new HashMap<>();
        initialPoints.put("Robot-A", new Point(0, 0));
        initialPoints.put("Robot-B", new Point(10, 10));
        initialPoints.put("Robot-C", new Point(50, 50));

        DelegatingRobotTracker tracker = new DelegatingRobotTracker(initialPoints);

        System.out.println("Starting Concurrent Robot Tracker Simulation...");
        System.out.println("Initial State: " + tracker.getLocationsLive());

        // 2. Create Executor with exactly 2 threads (plus main thread = 3 max)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // 3. Task: The "Updater" - Moves robots randomly
        Runnable updaterTask = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    // Move Robot-A
                    int newX = i * 10;
                    int newY = i * 10;
                    tracker.setLocation("Robot-A", newX, newY);
                    System.out.println("[Updater] Moved Robot-A to " + newX + "," + newY);

                    // Attempt to move a non-existent robot
                    if (i == 0) {
                        tracker.setLocation("Robot-Ghost", 99, 99);
                    }

                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // 4. Task: The "Monitor" - Compares Live View vs Snapshot
        Runnable monitorTask = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    // Take a static snapshot
                    Map<String, Point> snapshot = tracker.getLocationsSnapshot();

                    // Sleep briefly to allow the Updater to change the real data
                    Thread.sleep(50);

                    // Get the live view
                    Map<String, Point> live = tracker.getLocationsLive();

                    System.out.println("\n[Monitor] Cycle " + i);
                    System.out.println("   Snapshot (Static): " + snapshot.get("Robot-A"));
                    System.out.println("   Live View (Real) : " + live.get("Robot-A"));
                    System.out.println("   Are views equal? : " + snapshot.equals(live));

                    Thread.sleep(70);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // 5. Execute tasks
        executor.submit(updaterTask);
        executor.submit(monitorTask);

        // 6. Shutdown and wait
        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("\nSimulation finished.");
        System.out.println("Final State: " + tracker.getLocationsLive());
    }
}

