import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SolarSquirrels {

    private final List<String> identifiersList;
    private final Set<String> identifiersSet;

    public SolarSquirrels() {
        List<String> rawList = Arrays.asList("Nutty", "Whisk", "Fidget");
        this.identifiersList = Collections.unmodifiableList(rawList);
        this.identifiersSet = Collections.unmodifiableSet(new HashSet<>(rawList));
    }

    public boolean isSquirrel(String identifier) {
        return identifiersSet.contains(identifier);
    }

    public String getSquirrelIdentifiers() {
        return identifiersList.toString();
    }

    public static void main(String[] args) {
        SolarSquirrels squirrels = new SolarSquirrels();

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            String listOutput = squirrels.getSquirrelIdentifiers();
            System.out.println("Thread " + Thread.currentThread().getId() + " retrieved list: " + listOutput);
            String check = "Nutty";
            System.out.println("Thread " + Thread.currentThread().getId() + " checking " + check + ": " + squirrels.isSquirrel(check));
        };

        Runnable task2 = () -> {
            String check1 = "Whisk";
            String check2 = "Ratty";
            System.out.println("Thread " + Thread.currentThread().getId() + " checking " + check1 + ": " + squirrels.isSquirrel(check1));
            System.out.println("Thread " + Thread.currentThread().getId() + " checking " + check2 + ": " + squirrels.isSquirrel(check2));
        };

        executorService.execute(task1);
        executorService.execute(task2);

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

