import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MysticMantas {

    private final List<String> orderedTags;
    private final Set<String> lookupTags;

    public MysticMantas() {
        List<String> tags = Arrays.asList("Glimmer", "Ripple", "Twist");
        this.orderedTags = Collections.unmodifiableList(tags);
        this.lookupTags = Collections.unmodifiableSet(new HashSet<>(tags));
    }

    public boolean isManta(String tag) {
        return lookupTags.contains(tag);
    }

    public String getMantaTags() {
        return orderedTags.toString();
    }

    public static void main(String[] args) {
        MysticMantas mantas = new MysticMantas();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            String search = "Glimmer";
            System.out.println("Thread " + Thread.currentThread().getName() + " checking '" + search + "': " + mantas.isManta(search));
        });

        executor.submit(() -> {
            String search = "Bubble";
            System.out.println("Thread " + Thread.currentThread().getName() + " checking '" + search + "': " + mantas.isManta(search));
        });

        executor.submit(() -> {
            System.out.println("Thread " + Thread.currentThread().getName() + " listing tags: " + mantas.getMantaTags());
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
