                System.out.println("Task 1 (L1->L2) success: " + success);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (NotEnoughItemsException e) {
                System.out.println("Task 1 failed: " + e.getMessage());
            }
        };

        Runnable task2 = () -> {
            try {
                boolean success = system.move(locker2, locker1, 10, 2000, TimeUnit.MILLISECONDS);
                System.out.println("Task 2 (L2->L1) success: " + success);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (NotEnoughItemsException e) {
                System.out.println("Task 2 failed: " + e.getMessage());
            }
