        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    public boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) throws InterruptedException, NotEnoughItemsException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        Random random = new Random();

        while (System.nanoTime() < deadline) {
            if (source.lock.tryLock(10, TimeUnit.MILLISECONDS)) {
                try {
                    if (target.lock.tryLock(10, TimeUnit.MILLISECONDS)) {
                        try {
                            if (source.parcelCount.getCount() < quantity) {
                                throw new NotEnoughItemsException("Not enough items in source locker");
                            }
                            source.parcelCount.decrease(quantity);
                            target.parcelCount.increase(quantity);
                            return true;
                        } finally {
                            target.lock.unlock();
                        }
                    }
                } finally {
                    source.lock.unlock();
                }
            }

            long delay = getFixedDelay() + getRandomDelay(random);
            TimeUnit.MILLISECONDS.sleep(delay);
        }
        return false;
    }

    private long getFixedDelay() {
        return 20;
    }

    private long getRandomDelay(Random random) {
        return random.nextInt(50);
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        private int count;

        public ParcelCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void increase(int amount) {
            this.count += amount;
        }

        public void decrease(int amount) {
            this.count -= amount;
        }
    }

    static class Locker {
        final Lock lock = new ReentrantLock();
        final ParcelCount parcelCount;

        public Locker(int initialItems) {
            this.parcelCount = new ParcelCount(initialItems);
        }
    }
}

