import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ConcurrentParcelMover {

    public static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        private int count;

        public ParcelCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void increase(int amount) {
            this.count += amount;
        }

        public void decrease(int amount) {
            this.count -= amount;
        }
    }

    static class Locker {
        private final String id;
        private final ParcelCount parcelCount;
        private final ReentrantLock lock;

        public Locker(String id, int initialItems) {
            this.id = id;
            this.parcelCount = new ParcelCount(initialItems);
            this.lock = new ReentrantLock();
        }

        public String getId() {
            return id;
        }

        public ParcelCount getParcelCount() {
            return parcelCount;
        }

        public ReentrantLock getLock() {
            return lock;
        }
    }

    private static long getFixedDelay() {
        return 10; 
    }

    private static long getRandomDelay() {
        return new Random().nextInt(50); 
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) 
            throws InterruptedException, NotEnoughItemsException {

        long startNanos = System.nanoTime();
        long timeoutNanos = unit.toNanos(timeout);

        while ((System.nanoTime() - startNanos) < timeoutNanos) {
            if (source.getLock().tryLock(0, TimeUnit.SECONDS)) {
                try {
                    if (target.getLock().tryLock(0, TimeUnit.SECONDS)) {
                        try {
                            if (source.getParcelCount().getCount() < quantity) {
                                throw new NotEnoughItemsException("Insufficient items in locker " + source.getId());
                            }

                            source.getParcelCount().decrease(quantity);
                            target.getParcelCount().increase(quantity);

                            System.out.println(Thread.currentThread().getName() + " successfully moved " + quantity + 
                                               " parcels from " + source.getId() + " to " + target.getId());
                            return true;
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    source.getLock().unlock();
                }
            }

            long remainingNanos = timeoutNanos - (System.nanoTime() - startNanos);
            if (remainingNanos <= 0) {
                return false;
            }

            long delayMs = getFixedDelay() + getRandomDelay();
            long sleepTime = Math.min(delayMs, TimeUnit.NANOSECONDS.toMillis(remainingNanos) + 1);
            TimeUnit.MILLISECONDS.sleep(sleepTime);
        }

        return false;
    }

    public static void main(String[] args) {
        Locker lockerA = new Locker("A", 100);
        Locker lockerB = new Locker("B", 100);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    boolean moved = move(lockerA, lockerB, 10, 500, TimeUnit.MILLISECONDS);
                    if (!moved) {
                        System.out.println(Thread.currentThread().getName() + " timed out moving from A to B");
                    }
                    Thread.sleep(20);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
