                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("Final count A: " + lockerA.getParcelCount().getCount());
        System.out.println("Final count B: " + lockerB.getParcelCount().getCount());
    }
}

