import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ConcurrentWidgetMover {

    public static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }

    static class WidgetCount {
        private int count;

        public WidgetCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }
    }

    static class Bin {
        private final String id;
        private final ReentrantLock lock;
        private final WidgetCount widgetCount;

        public Bin(String id, int count) {
            this.id = id;
            this.lock = new ReentrantLock();
            this.widgetCount = new WidgetCount(count);
        }

        public String getId() {
            return id;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public WidgetCount getWidgetCount() {
            return widgetCount;
        }
    }

    /**
     * Helper method to get a fixed delay component in milliseconds.
     */
    private long getFixedDelayComponent() {
        return 10; 
    }

    /**
     * Helper method to get a random delay component in milliseconds.
     */
    private long getRandomDelayComponent() {
        return ThreadLocalRandom.current().nextLong(10, 50);
    }

    /**
     * Moves widgets from source bin to target bin with deadlock avoidance.
     */
    public boolean move(Bin source, Bin target, int amount, long timeout, TimeUnit unit) 
            throws NotEnoughWidgetsException, InterruptedException {

        long deadline = System.nanoTime() + unit.toNanos(timeout);

        while (System.nanoTime() < deadline) {
            boolean sourceLocked = false;
            boolean targetLocked = false;

            try {
                // Attempt to acquire the source lock with a short timeout
                sourceLocked = source.getLock().tryLock(10, TimeUnit.MILLISECONDS);
                if (sourceLocked) {
                    // Attempt to acquire the target lock with a short timeout
                    targetLocked = target.getLock().tryLock(10, TimeUnit.MILLISECONDS);
                    if (targetLocked) {
                        // Both locks acquired, perform business logic
                        if (source.getWidgetCount().getCount() >= amount) {
                            source.getWidgetCount().setCount(source.getWidgetCount().getCount() - amount);
                            target.getWidgetCount().setCount(target.getWidgetCount().getCount() + amount);
                            System.out.println(Thread.currentThread().getName() + " moved " + amount + 
                                " widgets from " + source.getId() + " to " + target.getId());
                            return true;
                        } else {
                            throw new NotEnoughWidgetsException("Not enough widgets in source bin " + source.getId());
                        }
                    }
                }
            } finally {
                if (targetLocked) {
                    target.getLock().unlock();
                }
                if (sourceLocked) {
                    source.getLock().unlock();
                }
            }

            // If we are here, we failed to acquire both locks; apply random pause pattern
            long remainingNanos = deadline - System.nanoTime();
            if (remainingNanos <= 0) {
