            }

            long delayMs = getFixedDelayComponent() + getRandomDelayComponent();
            long delayNanos = TimeUnit.MILLISECONDS.toNanos(delayMs);

            // Sleep for the calculated delay or the remaining time, whichever is smaller
            long sleepNanos = Math.min(delayNanos, remainingNanos);
            if (sleepNanos > 0) {
                TimeUnit.NANOSECONDS.sleep(sleepNanos);
            }
        }

        return false;
    }

