public class PersonSet {

    public interface Person {
        String getName();
    }

    private final Set<Person> mySet = new HashSet<>();

    public synchronized void addPerson(Person p) {
        mySet.add(p);
        System.out.println(Thread.currentThread().getName() + " added person: " + p.getName());
    }

    public synchronized boolean containsPerson(Person p) {
        boolean exists = mySet.contains(p);
        System.out.println(Thread.currentThread().getName() + " checked person " + p.getName() + ": " + exists);
        return exists;
    }

    private static class SimplePerson implements Person {
        private final String name;

        public SimplePerson(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            SimplePerson that = (SimplePerson) o;
            return name != null ? name.equals(that.name) : that.name == null;
        }

        public int hashCode() {
            return name != null ? name.hashCode() : 0;
        }
    }

    public static void main(String[] args) {
        PersonSet sharedSet = new PersonSet();

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Person alice = new SimplePerson("Alice");
        Person bob = new SimplePerson("Bob");
        Person charlie = new SimplePerson("Charlie");

        executorService.submit(() -> {
            try {
                sharedSet.addPerson(alice);
                Thread.sleep(100);
                sharedSet.addPerson(bob);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
