import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PersonSet {

    public interface Person {
        String getName();
    }

    private final Set<Person> mySet = new HashSet<>();

    public synchronized void addPerson(Person p) {
        mySet.add(p);
        System.out.println(Thread.currentThread().getName() + " added: " + p.getName());
    }

    public synchronized boolean containsPerson(Person p) {
        return mySet.contains(p);
    }

    private static class PersonImpl implements Person {
        private final String name;

        PersonImpl(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            PersonImpl person = (PersonImpl) o;
            return name != null ? name.equals(person.name) : person.name == null;
        }

        public int hashCode() {
            return name != null ? name.hashCode() : 0;
        }
    }

    public static void main(String[] args) {
        PersonSet personSet = new PersonSet();

        // Create a fixed thread pool with 2 threads.
        // Total threads = 1 (main) + 2 (pool) = 3.
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> {
            for (int i = 0; i < 10; i++) {
                Person p = new PersonImpl("Person-" + i);
                personSet.addPerson(p);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        executor.execute(() -> {
            for (int i = 0; i < 10; i++) {
                Person p = new PersonImpl("Person-" + i);
                boolean exists = personSet.containsPerson(p);
                System.out.println(Thread.currentThread().getName() + " check " + p.getName() + ": " + exists);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

