import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;

    public PublishingVehicleTracker(Map<String, SafePoint> points) {
        this.locations = new ConcurrentHashMap<>(points);
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, SafePoint> getLocations() {
        return unmodifiableMap;
    }

    public SafePoint getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (!locations.containsKey(id)) {
            throw new IllegalArgumentException("Vehicle ID does not exist: " + id);
        }
        locations.get(id).set(x, y);
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initialData = new HashMap<>();
        initialData.put("Truck-A", new SafePoint(0, 0));
        initialData.put("Taxi-B", new SafePoint(10, 10));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialData);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    tracker.setLocation("Truck-A", i * 5, i * 5);
                    System.out.println("Updater updated Truck-A to " + (i * 5) + "," + (i * 5));
                    Thread.sleep(50);
                }

                try {
                    tracker.setLocation("Ghost-Car", 0, 0);
                } catch (IllegalArgumentException e) {
                    System.out.println("Updater caught expected exception: " + e.getMessage());
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.execute(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    Map<String, SafePoint> allLocations = tracker.getLocations();
                    SafePoint p = allLocations.get("Truck-A");
                    if (p != null) {
                        int[] xy = p.get();
                        System.out.println("Reader read Truck-A position: " + xy[0] + "," + xy[1]);
                    }
                    Thread.sleep(50);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(2, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

class SafePoint {
    private int x;
    private int y;

    public SafePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public SafePoint(SafePoint p) {
        this(p.get());
    }

    public SafePoint(int[] a) {
        this(a[0], a[1]);
    }

    public synchronized int[] get() {
        return new int[]{x, y};
    }

    public synchronized void set(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

