import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PublishingVehicleTracker {

    private final Map<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;

    public PublishingVehicleTracker(Map<String, SafePoint> locations) {
        this.locations = new ConcurrentHashMap<>(locations);
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, SafePoint> getLocations() {
        return unmodifiableMap;
    }

    public SafePoint getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (!locations.containsKey(id)) {
            throw new IllegalArgumentException("Vehicle ID does not exist: " + id);
        }
        locations.put(id, new SafePoint(x, y));
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initialData = new HashMap<>();
        initialData.put("Vehicle-1", new SafePoint(0, 0));
        initialData.put("Vehicle-2", new SafePoint(100, 100));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialData);

        // Create a thread pool with 2 threads (Total threads: 1 Main + 2 Workers = 3)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Thread 1: Writer (Updates Vehicle-1)
        executor.submit(() -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    tracker.setLocation("Vehicle-1", i * 10, i * 10);
                    System.out.println("Writer moved Vehicle-1 to (" + (i * 10) + ", " + (i * 10) + ")");
                    Thread.sleep(50);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        // Thread 2: Reader (Reads Map)
        executor.submit(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    Map<String, SafePoint> currentLocs = tracker.getLocations();
                    SafePoint v1 = currentLocs.get("Vehicle-1");
                    if (v1 != null) {
                        System.out.println("Reader observed Vehicle-1 at (" + v1.getX() + ", " + v1.getY() + ")");
                    }
                    Thread.sleep(50);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

