import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class GrimoireInscription {

    enum Constellation {
        DRACO, ORION, CYGNUS, LYRA, PEGASUS
    }

    enum Resonance {
        SOLAR, LUNAR;

        public boolean isOpposite(Resonance other) {
            return this != other;
        }
    }

    static class Rune {
        private final Constellation constellation;
        private final Resonance resonance;

        public Rune(Constellation constellation, Resonance resonance) {
            this.constellation = constellation;
            this.resonance = resonance;
        }

        public Constellation getConstellation() {
            return constellation;
        }

        public Resonance getResonance() {
            return resonance;
        }
    }

    static class Harmony {
        private final Rune first;
        private final Rune second;

        public Harmony(Rune first, Rune second) {
            this.first = first;
            this.second = second;
        }
    }

    static class Grimoire {
        private final List<Harmony> crystallizedHarmonies = new ArrayList<>();

        public void crystallize(Harmony harmony) {
            crystallizedHarmonies.add(harmony);
        }

        public int getHarmonyCount() {
            return crystallizedHarmonies.size();
        }
    }

    public static int channelTheGrimoire(List<Rune> candidates) {
        Grimoire localGrimoire = new Grimoire();

        Comparator<Rune> runeSequencer = Comparator.comparing(Rune::getConstellation)
                                                   .thenComparing(Rune::getResonance);

        Collections.sort(candidates, runeSequencer);

        Deque<Rune> weavingStack = new LinkedList<>();

        for (Rune currentRune : candidates) {
            if (!weavingStack.isEmpty()) {
                Rune previousRune = weavingStack.peek();
                boolean sameConstellation = previousRune.getConstellation() == currentRune.getConstellation();
                boolean oppositeResonance = previousRune.getResonance().isOpposite(currentRune.getResonance());

                if (sameConstellation && oppositeResonance) {
                    weavingStack.pop();
                    Harmony harmony = new Harmony(previousRune, currentRune);
                    localGrimoire.crystallize(harmony);
                } else {
                    weavingStack.push(currentRune);
                }
            } else {
                weavingStack.push(currentRune);
            }
        }

        return localGrimoire.getHarmonyCount();
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Rune> batchAlpha = new ArrayList<>();
        List<Rune> batchOmega = new ArrayList<>();

        for (int i = 0; i < 5000; i++) {
            batchAlpha.add(new Rune(Constellation.ORION, Resonance.SOLAR));
            batchAlpha.add(new Rune(Constellation.ORION, Resonance.LUNAR));

            batchOmega.add(new Rune(Constellation.DRACO, Resonance.SOLAR));
            batchOmega.add(new Rune(Constellation.DRACO, Resonance.LUNAR));

            if (i % 3 == 0) {
                batchAlpha.add(new Rune(Constellation.CYGNUS, Resonance.SOLAR));
                batchOmega.add(new Rune(Constellation.LYRA, Resonance.LUNAR));
            }
        }

        Callable<Integer> taskAlpha = () -> channelTheGrimoire(batchAlpha);
        Callable<Integer> taskOmega = () -> channelTheGrimoire(batchOmega);

        try {
            Future<Integer> resultAlpha = executor.submit(taskAlpha);
            Future<Integer> resultOmega = executor.submit(taskOmega);

            int totalHarmonies = resultAlpha.get() + resultOmega.get();

            // Output the result to prevent code optimization removal, though logic is the goal
            if (totalHarmonies > 0) {
                System.out.println(totalHarmonies);
            }

        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions silently or print stack trace as needed
        } finally {
            executor.shutdown();
        }
    }
}

