                System.out.println(e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                tracker.setPerch("UnknownBeast", 10, 10);
            } catch (IllegalArgumentException e) {
                System.out.println(Thread.currentThread().getName() + " failed: " + e.getMessage());
            }
        });

        executor.submit(() -> {
            Map<String, Glyph> snapshot = tracker.getPerchesAsStatic();
            System.out.println(Thread.currentThread().getName() + " static snapshot: " + snapshot);
        });

        executor.submit(() -> {
            Glyph g = tracker.getPerch("CrystalGolem");
            System.out.println(Thread.currentThread().getName() + " read CrystalGolem: " + g);
        });

