import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MysticBeastTracker {

    private final ConcurrentMap<String, Glyph> perches;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        this.perches = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    public Glyph getPerch(String sigil) {
        return perches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        perches.compute(sigil, (key, existingGlyph) -> {
            if (existingGlyph == null) {
                throw new IllegalArgumentException("Beast with sigil '" + key + "' does not exist in the dreamscape.");
            }
            return new Glyph(spark, glimmer);
        });
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(perches));
    }

    public static void main(String[] args) {
        Map<String, Glyph> initialMap = new HashMap<>();
        initialMap.put("AetherWing", new Glyph(100, 200));
        initialMap.put("ShadowFox", new Glyph(50, 50));
        initialMap.put("StarWhale", new Glyph(1000, 5000));

        MysticBeastTracker tracker = new MysticBeastTracker(initialMap);
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Task 1: Update existing beast
        executor.submit(() -> {
            try {
                String beast = "AetherWing";
                System.out.println(Thread.currentThread().getName() + " moving " + beast);
                tracker.setPerch(beast, 120, 220);
                System.out.println(Thread.currentThread().getName() + " moved " + beast + " to " + tracker.getPerch(beast));
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        // Task 2: Attempt to update non-existent beast
        executor.submit(() -> {
            try {
                String beast = "VoidSerpent";
                System.out.println(Thread.currentThread().getName() + " attempting to move missing beast " + beast);
                tracker.setPerch(beast, 0, 0);
            } catch (IllegalArgumentException e) {
                System.out.println(Thread.currentThread().getName() + " caught expected exception: " + e.getMessage());
            }
        });

        // Task 3: Read static snapshot
        executor.submit(() -> {
