import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ArcaneEnchantment {

    public interface Talisman<T> {
        T enchant();
    }

    public interface SigilNode<T> {
        T compute();
        List<SigilNode<T>> getChildren();
    }

    public static <T> List<T> weaveSequentially(List<Talisman<T>> talismans) {
        List<T> results = new ArrayList<>();
        for (Talisman<T> talisman : talismans) {
            results.add(talisman.enchant());
        }
        return results;
    }

    public static <T> List<T> weaveSimultaneously(List<Talisman<T>> talismans, ExecutorService executor) {
        List<Callable<T>> tasks = new ArrayList<>();
        for (Talisman<T> talisman : talismans) {
            tasks.add(talisman::enchant);
        }

        List<T> results = new ArrayList<>();
        try {
            List<Future<T>> futures = executor.invokeAll(tasks);
            for (Future<T> future : futures) {
                results.add(future.get());
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Conjuration interrupted or failed", e);
        }
        return results;
    }

    public static <T> void traverseSigilSequentially(SigilNode<T> node, List<T> collection) {
        if (node == null) return;

        collection.add(node.compute());

        List<SigilNode<T>> children = node.getChildren();
        if (children != null) {
            for (SigilNode<T> child : children) {
                traverseSigilSequentially(child, collection);
            }
        }
    }

    public static <T> List<T> traverseSigilSimultaneously(SigilNode<T> root, ExecutorService executor) {
        List<Callable<T>> tasks = new ArrayList<>();
        collectSigilTasks(root, tasks);

        List<T> results = new ArrayList<>();
        try {
            List<Future<T>> futures = executor.invokeAll(tasks);
            for (Future<T> future : futures) {
                results.add(future.get());
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Grove traversal failed", e);
        }
        return results;
    }

    private static <T> void collectSigilTasks(SigilNode<T> node, List<Callable<T>> tasks) {
        if (node == null) return;
        tasks.add(node::compute);
        List<SigilNode<T>> children = node.getChildren();
        if (children != null) {
            for (SigilNode<T> child : children) {
                collectSigilTasks(child, tasks);
            }
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        try {
            List<Talisman<String>> amulets = new ArrayList<>();
            for (int i = 1; i <= 5; i++) {
                final int id = i;
                amulets.add(() -> {
                    String threadName = Thread.currentThread().getName();
                    return "Amulet " + id + " enchanted by " + threadName;
                });
            }

            List<String> seqResults = weaveSequentially(amulets);
            List<String> parResults = weaveSimultaneously(amulets, executor);

            Rune root = new Rune("Alpha");
            Rune child1 = new Rune("Beta");
            Rune child2 = new Rune("Gamma");
            root.addChild(child1);
            root.addChild(child2);
            child1.addChild(new Rune("Delta"));
            child2.addChild(new Rune("Epsilon"));

            List<String> groveSeqResults = new ArrayList<>();
            traverseSigilSequentially(root, groveSeqResults);

            List<String> groveParResults = traverseSigilSimultaneously(root, executor);

        } finally {
            executor.shutdown();
        }
    }

    static class Rune implements SigilNode<String> {
        private final String name;
        private final List<SigilNode<String>> children;

        public Rune(String name) {
            this.name = name;
            this.children = new ArrayList<>();
        }

        public void addChild(Rune child) {
            this.children.add(child);
        }

        public String compute() {
            return "Rune " + name + " active on " + Thread.currentThread().getName();
        }

        public List<SigilNode<String>> getChildren() {
            return children;
        }
    }
}

