            System.out.println("Parallel Talisman Results: " + parTalismanResults.size());

            // 4. Prepare Sigil Forest
            ArcaneNode root = new ArcaneNode("Root");
            ArcaneNode child1 = new ArcaneNode("Child-1");
            ArcaneNode child2 = new ArcaneNode("Child-2");
            root.addChild(child1);
            root.addChild(child2);
            child1.addChild(new ArcaneNode("Leaf-1A"));
            child1.addChild(new ArcaneNode("Leaf-1B"));
            child2.addChild(new ArcaneNode("Leaf-2A"));

            // 5. Recursive Sequential Sigil Processing
            List<String> seqSigilResults = new ArrayList<>();
            processSigilForestSequential(root, seqSigilResults);
            System.out.println("Sequential Sigil Results: " + seqSigilResults.size());

            // 6. Recursive Parallel Sigil Processing
            List<String> parSigilResults = processSigilForestParallel(root, executor);
            System.out.println("Parallel Sigil Results: " + parSigilResults.size());

        } finally {
            executor.shutdown();
        }
    }

    // --- Sequential Talisman Processing ---
    public static <T> List<T> processTalismansSequential(List<Talisman<T>> talismans) {
        List<T> results = new ArrayList<>();
        for (Talisman<T> t : talismans) {
