        List<Future<T>> futures = new ArrayList<>();
        List<T> results = new ArrayList<>();

        // Dispatch
        for (Talisman<T> t : talismans) {
            Callable<T> task = () -> t.activate();
            futures.add(executor.submit(task));
        }

        // Collect
        for (Future<T> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions appropriately, keeping thread safety in mind
                Thread.currentThread().interrupt();
            }
        }
        return results;
    }

    // --- Recursive Sequential Sigil Processing ---
    public static <T> void processSigilForestSequential(SigilNode<T> node, List<T> results) {
        if (node == null) return;

        results.add(node.compute());

        for (SigilNode<T> child : node.getChildren()) {
            processSigilForestSequential(child, results);
        }
    }

    // --- Recursive Parallel Sigil Processing ---
    public static <T> List<T> processSigilForestParallel(SigilNode<T> root, ExecutorService executor) {
        List<Future<T>> futures = new ArrayList<>();

        // Traverse recursively to submit tasks, avoiding deadlocks by not waiting inside the tasks
        submitSigilRecursively(root, executor, futures);

        // Wait for all tasks to complete and collect results
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }
        return results;
    }

    private static <T> void submitSigilRecursively(SigilNode<T> node, ExecutorService executor, List<Future<T>> futures) {
        if (node == null) return;

        Callable<T> task = () -> node.compute();
        futures.add(executor.submit(task));

        for (SigilNode<T> child : node.getChildren()) {
            submitSigilRecursively(child, executor, futures);
        }
    }
