import java.util.concurrent.Future;

public class ConcurrentSummoner {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        try {
            // 1. Talisman Processing
            List<Talisman<String>> talismans = new ArrayList<>();
            talismans.add(new SpellTalisman("Fire"));
            talismans.add(new SpellTalisman("Ice"));
