            System.out.println("Parallel Talismans: " + parTalismanResults);

            // 2. Sigil Forest Processing
            SigilNode<Integer> leaf1 = new PowerSigil(10, Collections.emptyList());
            SigilNode<Integer> leaf2 = new PowerSigil(20, Collections.emptyList());
            SigilNode<Integer> root1 = new PowerSigil(5, Arrays.asList(leaf1, leaf2));
            SigilNode<Integer> root2 = new PowerSigil(100, Collections.emptyList());

            List<SigilNode<Integer>> forest = Arrays.asList(root1, root2);

            List<Integer> seqSigilResults = processSigilsSequential(forest);
            System.out.println("Sequential Sigils: " + seqSigilResults);

            List<Integer> parSigilResults = processSigilsParallel(forest, executor);
            System.out.println("Parallel Sigils: " + parSigilResults);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    // --- Processing Methods ---

    public static <R> List<R> processTalismansSequential(List<Talisman<R>> talismans) {
        List<R> results = new ArrayList<>();
        for (Talisman<R> t : talismans) {
            results.add(t.activate());
        }
        return results;
    }

    public static <R> List<R> processTalismansParallel(List<Talisman<R>> talismans, ExecutorService executor) throws InterruptedException, ExecutionException {
        List<Callable<R>> tasks = new ArrayList<>();
        for (Talisman<R> t : talismans) {
            tasks.add(t::activate);
        }

        List<Future<R>> futures = executor.invokeAll(tasks);
        List<R> results = new ArrayList<>();
        for (Future<R> f : futures) {
            results.add(f.get());
        }
        return results;
    }

    public static <R> List<R> processSigilsSequential(List<SigilNode<R>> forest) {
        List<R> results = new ArrayList<>();
        for (SigilNode<R> node : forest) {
            traverseSigilsSequential(node, results);
        }
        return results;
    }

    private static <R> void traverseSigilsSequential(SigilNode<R> node, List<R> results) {
        results.add(node.compute());
        for (SigilNode<R> child : node.getChildren()) {
            traverseSigilsSequential(child, results);
        }
    }

    public static <R> List<R> processSigilsParallel(List<SigilNode<R>> forest, ExecutorService executor) throws InterruptedException, ExecutionException {
        // Collect Futures to ensure completion
        List<Future<R>> futures = new ArrayList<>();
        // Thread-safe collection for results if we were to collect within tasks, 
        // though here we extract from Futures to guarantee order and completion.

        for (SigilNode<R> node : forest) {
            traverseSigilsParallel(node, executor, futures);
        }

        List<R> results = new ArrayList<>();
        for (Future<R> f : futures) {
            results.add(f.get());
        }
        return results;
    }

    private static <R> void traverseSigilsParallel(SigilNode<R> node, ExecutorService executor, List<Future<R>> futures) {
        // Submit current computation to the pool
        futures.add(executor.submit(node::compute));

        // Recursively traverse children in the current thread to dispatch their tasks
        // This avoids blocking worker threads on child results (preventing deadlock in small pools)
        if (node.getChildren() != null) {
            for (SigilNode<R> child : node.getChildren()) {
                traverseSigilsParallel(child, executor, futures);
            }
        }
    }

