class Orb {
    private final int powerLevel;

    public Orb(int powerLevel) {
        this.powerLevel = powerLevel;
    }

    public String toString() {
        return "Orb-" + powerLevel;
    }
}

class MagicalOrbVault {
    private final Orb[] storage;
    private final int capacity;
    private int head;
    private int tail;
    private int count;

    private final Semaphore availableOrbs;
    private final Semaphore remainingSlots;
    private final Object lock;

    public MagicalOrbVault(int capacity) {
        this.capacity = capacity;
        this.storage = new Orb[capacity];
        this.head = 0;
        this.tail = 0;
        this.count = 0;
        this.lock = new Object();

        this.availableOrbs = new Semaphore(0);
        this.remainingSlots = new Semaphore(capacity);
    }

    public void put(Orb x) {
        try {
            remainingSlots.acquire();
            synchronized (lock) {
                storage[tail] = x;
                tail = (tail + 1) % capacity;
                count++;
                System.out.println(Thread.currentThread().getName() + " placed " + x + " [Count: " + count + "]");
            }
            availableOrbs.release();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public Orb take() {
        Orb x = null;
        try {
            availableOrbs.acquire();
            synchronized (lock) {
                x = storage[head];
                storage[head] = null;
                head = (head + 1) % capacity;
                count--;
                System.out.println(Thread.currentThread().getName() + " retrieved " + x + " [Count: " + count + "]");
            }
            remainingSlots.release();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return x;
    }

    public boolean isEmpty() {
        synchronized (lock) {
            return count == 0;
        }
    }

    public boolean isFull() {
        synchronized (lock) {
            return count == capacity;
        }
    }
}

