import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ChronomanticDragonTracker {

    private final Constellation<String, MutableOrb> internalConstellation;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initial) {
        this.internalConstellation = deepClone(initial);
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
        Constellation<String, MutableOrb> copy = deepClone(this.internalConstellation);
        copy.lock();
        return copy;
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb original = this.internalConstellation.get(sigil);
        if (original == null) {
            return null;
        }
        return new MutableOrb(original.getShimmerX(), original.getShimmerY());
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!this.internalConstellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found: " + sigil);
        }
        MutableOrb orb = this.internalConstellation.get(sigil);
        orb.setShimmerX(shimmerX);
        orb.setShimmerY(shimmerY);
    }

    private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> input) {
        Constellation<String, MutableOrb> clone = new Constellation<>();
        for (String key : input.keys()) {
            MutableOrb val = input.get(key);
            if (val != null) {
                clone.put(key, new MutableOrb(val.getShimmerX(), val.getShimmerY()));
            }
        }
        return clone;
    }

    public static void main(String[] args) {
        Constellation<String, MutableOrb> initialSetup = new Constellation<>();
        initialSetup.put("Bahamut", new MutableOrb(0, 0));
