        public Constellation() {
            super();
        }
        public Constellation(Map<? extends K, ? extends V> m) {
            super(m);
        }
    }

    public static class ChronomanticDragonTracker {
        private final Constellation<String, MutableOrb> internalConstellation;

        public ChronomanticDragonTracker(Constellation<String, MutableOrb> initial) {
            this.internalConstellation = deepClone(initial);
        }

        public synchronized Map<String, MutableOrb> getConstellations() {
            return Collections.unmodifiableMap(deepClone(internalConstellation));
        }

