public class CelestialGriffinTracker {

    private final Map<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(Map<String, MutableGem> initialMap) {
        this.starlightMap = deepForge(initialMap);
    }

    private static Map<String, MutableGem> deepForge(Map<String, MutableGem> input) {
        Map<String, MutableGem> copy = new HashMap<>();
        if (input != null) {
            for (Map.Entry<String, MutableGem> entry : input.entrySet()) {
                copy.put(entry.getKey(), new MutableGem(entry.getValue()));
            }
        }
        return copy;
    }

    public synchronized Map<String, MutableGem> getStarlights() {
        return Collections.unmodifiableMap(deepForge(this.starlightMap));
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem original = starlightMap.get(rune);
        if (original == null) {
            return null;
        }
        return new MutableGem(original);
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        if (!starlightMap.containsKey(rune)) {
            throw new IllegalArgumentException("Rune not present: " + rune);
        }
        MutableGem gem = starlightMap.get(rune);
        gem.setGlowX(glowX);
        gem.setGlowY(glowY);
    }

    public static void main(String[] args) {
        Map<String, MutableGem> initialData = new HashMap<>();
        initialData.put("Griffin-Alpha", new MutableGem(100, 200));
        initialData.put("Griffin-Beta", new MutableGem(50, 60));

        CelestialGriffinTracker tracker = new CelestialGriffinTracker(initialData);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(new Runnable() {
            public void run() {
                try {
                    String name = Thread.currentThread().getName();
                    System.out.println(name + " updating Griffin-Alpha...");
                    tracker.setGem("Griffin-Alpha", 888, 999);
                    System.out.println(name + " update complete.");
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });

        executor.submit(new Runnable() {
            public void run() {
                try {
                    String name = Thread.currentThread().getName();
                    Map<String, MutableGem> snapshot = tracker.getStarlights();
                    System.out.println(name + " retrieved starlights: " + snapshot);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(3, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("Main thread final check: " + tracker.getStarlights());
    }
}

