import java.util.Random;

public class DemonstrateDeadlock {
private static final int NUM_THREADS = 2;
private static final int NUM_ACCOUNTS = 2;
private static final int NUM_ITERATIONS = 10;

public static void main(String[] args) {
final Random rnd = new Random();
final Account[] accounts = new Account[NUM_ACCOUNTS];

for (int i = 0; i < accounts.length; i++)
accounts[i] = new Account();

class TransferThread extends Thread {
public void run() {
for (int i = 0; i < NUM_ITERATIONS; i++) {
int fromAcct = rnd.nextInt(NUM_ACCOUNTS);
int toAcct = rnd.nextInt(NUM_ACCOUNTS);
if (fromAcct == toAcct)
continue;
DollarAmount amount = new DollarAmount(rnd.nextInt(1000));
try {
DynamicOrderDeadlock.transferMoney(accounts[fromAcct], accounts[toAcct], amount);
} catch (DynamicOrderDeadlock.InsufficientFundsException ignored) {
}
}
}
}

for (int i = 0; i < NUM_THREADS; i++) {
new TransferThread().start();
}
}
}

class Account {
private volatile int balance;

public Account() {
this.balance = 1000;
}

public synchronized int getBalance() {
return balance;
}

public synchronized void setBalance(int balance) {
this.balance = balance;
}
}

class DollarAmount {
private final int value;

public DollarAmount(int value) {
this.value = value;
}

public int getValue() {
return value;
}
}

class DynamicOrderDeadlock {
public static void transferMoney(Account fromAcct, Account toAcct, DollarAmount amount)
throws InsufficientFundsException {
Account first = fromAcct;
Account second = toAcct;
if (System.identityHashCode(first) > System.identityHashCode(second)) {
first = toAcct;
second = fromAcct;
}

synchronized (first) {
synchronized (second) {
if (fromAcct.getBalance() < amount.getValue())
throw new InsufficientFundsException();
fromAcct.setBalance(fromAcct.getBalance() - amount.getValue());
toAcct.setBalance(toAcct.getBalance() + amount.getValue());
}
}
}

public static class InsufficientFundsException extends Exception {}
}

