/**
* A thread-safe integer wrapper using synchronized methods.
*/
public class LLMC {
private int value;

public LLMC(int initialValue) {
this.value = initialValue;
}

public LLMC() {
this(0);
}

public synchronized int get() {
return value;
}

public synchronized void set(int value) {
this.value = value;
}

public synchronized int increment() {
return ++value;
}

public static void main(String[] args) throws InterruptedException {
LLMC counter = new LLMC();

final int NUM_THREADS = 2;
final int INCREMENTS_PER_THREAD = 2;

Thread[] threads = new Thread[NUM_THREADS];

for (int i = 0; i < NUM_THREADS; i++) {
threads[i] = new Thread(() -> {
for (int j = 0; j < INCREMENTS_PER_THREAD; j++) {
counter.increment();
}
});
threads[i].start();
}

for (Thread t : threads) {
t.join();
}

System.out.println("Final counter value: " + counter.get());
System.out.println("Expected value: " + (NUM_THREADS * INCREMENTS_PER_THREAD));
}
}

