import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ArkLoader {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Animal> batchOne = new ArrayList<>();
        batchOne.add(new Animal(Species.LION, Gender.MALE));
        batchOne.add(new Animal(Species.LION, Gender.FEMALE));
        batchOne.add(new Animal(Species.ZEBRA, Gender.MALE));
        batchOne.add(new Animal(Species.ZEBRA, Gender.FEMALE));
        batchOne.add(new Animal(Species.GIRAFFE, Gender.MALE));
        batchOne.add(new Animal(Species.GIRAFFE, Gender.MALE));

        List<Animal> batchTwo = new ArrayList<>();
        batchTwo.add(new Animal(Species.ELEPHANT, Gender.FEMALE));
        batchTwo.add(new Animal(Species.ELEPHANT, Gender.MALE));
        batchTwo.add(new Animal(Species.LION, Gender.MALE));
        batchTwo.add(new Animal(Species.LION, Gender.FEMALE));
        batchTwo.add(new Animal(Species.ZEBRA, Gender.FEMALE));

        Callable<Integer> taskOne = () -> loadTheArk(batchOne);
        Callable<Integer> taskTwo = () -> loadTheArk(batchTwo);

        try {
            Future<Integer> resultOne = executor.submit(taskOne);
            Future<Integer> resultTwo = executor.submit(taskTwo);

            System.out.println("Pairs from batch 1: " + resultOne.get());
            System.out.println("Pairs from batch 2: " + resultTwo.get());
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    public static int loadTheArk(List<Animal> animals) {
        Ark ark = new Ark();

        Comparator<Animal> sorter = Comparator.comparing(Animal::getSpecies)
                                              .thenComparing(Animal::getGender);

        Collections.sort(animals, sorter);

        for (int i = 0; i < animals.size() - 1; i++) {
            Animal a1 = animals.get(i);
            Animal a2 = animals.get(i + 1);

            if (a1.getSpecies() == a2.getSpecies() && a1.getGender() != a2.getGender()) {
                ark.addPair(new AnimalPair(a1, a2));
                i++; 
            }
        }

        return ark.getPairCount();
    }
}

