import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ArkLoadingSimulation {

    enum Species {
        LION, TIGER, ZEBRA, ELEPHANT, GIRAFFE, MONKEY
    }

    enum Gender {
        MALE, FEMALE
    }

    static class Animal {
        private final Species species;
        private final Gender gender;
        private final String id;

        Animal(Species species, Gender gender, String id) {
            this.species = species;
            this.gender = gender;
            this.id = id;
        }

        public Species getSpecies() {
            return species;
        }

        public Gender getGender() {
            return gender;
        }

        public String toString() {
            return species + "(" + gender + "-" + id + ")";
        }
    }

    static class AnimalPair {
        private final Animal first;
        private final Animal second;

        AnimalPair(Animal first, Animal second) {
            this.first = first;
            this.second = second;
        }

        public String toString() {
            return "[" + first + " & " + second + "]";
        }
    }

    static class Ark {
        private final List<AnimalPair> pairs = new ArrayList<>();

        public synchronized void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        public synchronized int getTotalPairs() {
            return pairs.size();
        }

        public synchronized void printManifest() {
            for (AnimalPair p : pairs) {
                System.out.println("Loaded: " + p);
            }
        }
    }

    public static void main(String[] args) {
        Ark ark = new Ark();

        // Creating candidate lists for different threads
        List<Animal> group1 = new ArrayList<>();
        group1.add(new Animal(Species.LION, Gender.MALE, "1"));
        group1.add(new Animal(Species.LION, Gender.FEMALE, "2"));
        group1.add(new Animal(Species.ZEBRA, Gender.MALE, "3"));
        group1.add(new Animal(Species.ZEBRA, Gender.FEMALE, "4"));
        group1.add(new Animal(Species.ELEPHANT, Gender.MALE, "5"));

        List<Animal> group2 = new ArrayList<>();
        group2.add(new Animal(Species.TIGER, Gender.FEMALE, "6"));
        group2.add(new Animal(Species.TIGER, Gender.MALE, "7"));
        group2.add(new Animal(Species.TIGER, Gender.MALE, "8"));
        group2.add(new Animal(Species.GIRAFFE, Gender.FEMALE, "9"));
        group2.add(new Animal(Species.GIRAFFE, Gender.FEMALE, "10")); 
        group2.add(new Animal(Species.GIRAFFE, Gender.MALE, "11"));

        // Thread pool restricted to 2 threads + main thread = 3 max
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            int count = loadTheArk(group1, ark);
            System.out.println("Thread-1 formed " + count + " pairs.");
        });

        executor.submit(() -> {
            int count = loadTheArk(group2, ark);
            System.out.println("Thread-2 formed " + count + " pairs.");
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Total pairs on the Ark: " + ark.getTotalPairs());
        ark.printManifest();
    }

    static int loadTheArk(Collection<Animal> candidates, Ark ark) {
        // Thread confinement: Create a local copy to sort and process
        List<Animal> sortedAnimals = new ArrayList<>(candidates);

        // Sort by Species then Gender
        sortedAnimals.sort(Comparator.comparing(Animal::getSpecies)
                                     .thenComparing(Animal::getGender));

        int pairsFormed = 0;
        Deque<Animal> waitingArea = new ArrayDeque<>();

        for (Animal current : sortedAnimals) {
            if (waitingArea.isEmpty()) {
                waitingArea.push(current);
            } else {
                Animal candidate = waitingArea.peek();

                // Check if same species
                if (candidate.getSpecies() == current.getSpecies()) {
                    // Check if opposite gender
                    if (candidate.getGender() != current.getGender()) {
                        // Match found
                        waitingArea.pop();
                        AnimalPair pair = new AnimalPair(candidate, current);
                        ark.addPair(pair); // Thread-safe call
                        pairsFormed++;
                    } else {
                        // Same gender, cannot pair, wait
                        waitingArea.push(current);
                    }
                } else {
                    // Species changed, clear previous unpaired animals of different species
                    waitingArea.clear();
                    waitingArea.push(current);
                }
            }
        }

        return pairsFormed;
    }
}

import java.util.ArrayList;
