import java.util.concurrent.Future;

public class NoahsArkLoader {

    enum Species {
        LION, ZEBRA, ELEPHANT, GIRAFFE, HIPPO, MONKEY
    }

    enum Gender {
        MALE, FEMALE
    }

    static class Animal {
        private final Species species;
        private final Gender gender;

        Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        public Species getSpecies() {
            return species;
        }

        public Gender getGender() {
            return gender;
        }
    }

    static class AnimalPair {
        private final Animal one;
        private final Animal two;

        AnimalPair(Animal one, Animal two) {
            this.one = one;
            this.two = two;
        }
    }

    static class Ark {
        private final List<AnimalPair> pairs = new ArrayList<>();

        public void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        public int getPairCount() {
            return pairs.size();
        }
    }

    public static void main(String[] args) {
        // Fixed thread pool of 2 ensures total threads (including main) does not exceed 3
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Generate two batches of animals to load concurrently
        List<Animal> batchOne = generateAnimals(100);
        List<Animal> batchTwo = generateAnimals(150);

        Callable<Integer> taskOne = () -> loadTheArk(batchOne);
        Callable<Integer> taskTwo = () -> loadTheArk(batchTwo);

        try {
            Future<Integer> futureOne = executor.submit(taskOne);
            Future<Integer> futureTwo = executor.submit(taskTwo);

            int pairsFromBatchOne = futureOne.get();
            int pairsFromBatchTwo = futureTwo.get();
            int totalPairs = pairsFromBatchOne + pairsFromBatchTwo;

            System.out.println("Batch One Pairs: " + pairsFromBatchOne);
            System.out.println("Batch Two Pairs: " + pairsFromBatchTwo);
            System.out.println("Total Pairs Loaded: " + totalPairs);

        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    public static int loadTheArk(Collection<Animal> candidates) {
        // Thread confinement: Create a local copy of the list and local Ark
        List<Animal> sortedAnimals = new ArrayList<>(candidates);
        Ark localArk = new Ark();

        // Sort by Species then Gender
        Comparator<Animal> comparator = (a1, a2) -> {
            int speciesComparison = a1.getSpecies().compareTo(a2.getSpecies());
            if (speciesComparison != 0) {
                return speciesComparison;
            }
            return a1.getGender().compareTo(a2.getGender());
        };

        Collections.sort(sortedAnimals, comparator);

        // Pairing logic using a stack
        Deque<Animal> waitingArea = new ArrayDeque<>();

        for (Animal current : sortedAnimals) {
            if (waitingArea.isEmpty()) {
                waitingArea.push(current);
            } else {
                Animal waiting = waitingArea.peek();

                // Check if same species
                if (waiting.getSpecies() != current.getSpecies()) {
                    // Different species: clear waiting area (unpaired), push current
                    waitingArea.clear();
                    waitingArea.push(current);
                } else {
                    // Same species: check gender compatibility
                    if (waiting.getGender() != current.getGender()) {
                        // Compatible pair found
                        waitingArea.pop();
                        localArk.addPair(new AnimalPair(waiting, current));
                    } else {
                        // Same gender: cannot pair, add to waiting area
                        waitingArea.push(current);
                    }
                }
            }
        }

        return localArk.getPairCount();
    }

    private static List<Animal> generateAnimals(int count) {
        List<Animal> animals = new ArrayList<>();
        Random random = new Random();
        Species[] allSpecies = Species.values();
        Gender[] allGenders = Gender.values();

        for (int i = 0; i < count; i++) {
            Species s = allSpecies[random.nextInt(allSpecies.length)];
            Gender g = allGenders[random.nextInt(allGenders.length)];
            animals.add(new Animal(s, g));
        }
        return animals;
    }
}

