class OneValueCache {
    private final BigInteger lastNumber;
    private final BigInteger[] lastFactors;

    public OneValueCache(BigInteger i, BigInteger[] factors) {
        this.lastNumber = i;
        this.lastFactors = Arrays.copyOf(factors, factors.length);
    }

    public BigInteger[] getFactors(BigInteger i) {
        if (lastNumber == null || !lastNumber.equals(i)) {
            return null;
        }
        return Arrays.copyOf(lastFactors, lastFactors.length);
    }
}

class ServiceWrapper {
    private volatile OneValueCache cache = new OneValueCache(null, new BigInteger[0]);

    public void compute(BigInteger number) {
        BigInteger[] factors = cache.getFactors(number);
        if (factors == null) {
            factors = factor(number);
            cache = new OneValueCache(number, factors);
            System.out.println(Thread.currentThread().getName() + " Computed factors for " + number + ": " + Arrays.toString(factors));
        } else {
            System.out.println(Thread.currentThread().getName() + " Cache hit for " + number + ": " + Arrays.toString(factors));
        }
    }

    private BigInteger[] factor(BigInteger i) {
        List<BigInteger> list = new ArrayList<>();
        BigInteger temp = i;
        BigInteger two = new BigInteger("2");

        while (temp.mod(two).equals(BigInteger.ZERO)) {
            list.add(two);
            temp = temp.divide(two);
        }

        BigInteger d = new BigInteger("3");
        while (d.multiply(d).compareTo(temp) <= 0) {
            while (temp.mod(d).equals(BigInteger.ZERO)) {
                list.add(d);
                temp = temp.divide(d);
            }
            d = d.add(two);
        }

        if (temp.compareTo(BigInteger.ONE) > 0) {
            list.add(temp);
        }

        return list.toArray(new BigInteger[0]);
    }
}

