import java.util.concurrent.TimeUnit;

public class VolatileCacheExample {

    public static void main(String[] args) {
        VolatileCachedServlet servlet = new VolatileCachedServlet();

        // Constraint: Max 3 threads total (1 Main + 2 in Pool)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable[] tasks = new Runnable[] {
            () -> servlet.service(new BigInteger("88")),
            () -> servlet.service(new BigInteger("88")),
            () -> servlet.service(new BigInteger("99")),
            () -> servlet.service(new BigInteger("88")),
            () -> servlet.service(new BigInteger("99"))
        };

        for (Runnable task : tasks) {
            executor.execute(task);
        }

        executor.shutdown();
