class OneValueCache {
    private final BigInteger lastNumber;
    private final BigInteger[] lastFactors;

    public OneValueCache(BigInteger i, BigInteger[] factors) {
        this.lastNumber = i;
        // Defensive copy to ensure immutability
        this.lastFactors = factors == null ? null : Arrays.copyOf(factors, factors.length);
    }

    public BigInteger[] getFactors(BigInteger i) {
        if (lastNumber == null || !lastNumber.equals(i)) {
            return null;
        }
        // Return copy to ensure immutability
        return Arrays.copyOf(lastFactors, lastFactors.length);
    }
}

class VolatileCachedServlet {
    private volatile OneValueCache cache = new OneValueCache(null, null);

    public void service(BigInteger input) {
        BigInteger[] factors = cache.getFactors(input);

        if (factors == null) {
            factors = compute(input);
            cache = new OneValueCache(input, factors);
            System.out.println(Thread.currentThread().getName() + ": Cache Miss - Computed result for " + input);
        } else {
            System.out.println(Thread.currentThread().getName() + ": Cache Hit - Returned result for " + input);
        }
    }

    private BigInteger[] compute(BigInteger input) {
        // Simulating computation overhead
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        // Placeholder computation: returns input as single-element array
        return new BigInteger[] { input };
    }
}
