import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ConcurrentPointSystem {

    public static void main(String[] args) {
        // Create a thread pool with 5 threads. 
        // Total threads including main thread will be 6 (1 main + 5 workers).
        ExecutorService executorService = Executors.newFixedThreadPool(5);
        List<Future<String>> results = new ArrayList<>();

        // Submit tasks to the executor
        for (int i = 0; i < 10; i++) {
            final int valX = i;
            final int valY = i * 2;

            Callable<String> task = () -> {
                // Create an immutable Point instance
                Point point = new Point(valX, valY);

                // Perform a calculation using the point's coordinates
                // This simulates work being done in the concurrent thread
                double distance = Math.sqrt(point.x * point.x + point.y * point.y);

                return "Thread " + Thread.currentThread().getId() + 
                       " processed " + point.toString() + 
                       " | Distance from origin: " + distance;
            };

            results.add(executorService.submit(task));
        }

        // Retrieve and print results from the futures
        for (Future<String> future : results) {
            try {
                System.out.println(future.get());
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        // Shut down the executor service
        executorService.shutdown();
    }
}

