import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class VehicleTrackerApp {

    public static void main(String[] args) {
        // Initialize the initial locations
        Map<String, Point> initialPoints = new HashMap<>();
        initialPoints.put("Truck-1", new Point(0, 0));
        initialPoints.put("Taxi-1", new Point(10, 10));
        initialPoints.put("Sedan-1", new Point(20, 20));

        // Create the tracker instance
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialPoints);

        // Create a fixed thread pool with 2 threads. 
        // Total threads = 1 (Main) + 2 (Pool) = 3.
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Task 1: The Writer Thread
        // This thread simulates vehicles moving by updating their locations.
        Runnable writerTask = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    // Move Truck-1
                    tracker.setLocation("Truck-1", i * 5, i * 5);
                    System.out.println("[Writer] Moved Truck-1 to " + tracker.getLocation("Truck-1"));

                    // Move Taxi-1
                    tracker.setLocation("Taxi-1", 10 + i, 10 + i);
                    System.out.println("[Writer] Moved Taxi-1 to " + tracker.getLocation("Taxi-1"));

                    // Attempt to update a non-existent vehicle (should fail silently or return null)
                    tracker.setLocation("Ghost-Car", 99, 99);

                    Thread.sleep(100); // Simulate time passing between moves
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Task 2: The Reader Thread
        // This thread periodically reads the live view and the snapshot.
        Runnable readerTask = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    // 1. Get Live View
                    Map<String, Point> liveView = tracker.getLocations();
                    System.out.println("[Reader] Live View Truck-1: " + liveView.get("Truck-1"));

                    // 2. Get Snapshot
                    Map<String, Point> snapshot = tracker.getLocationsSnapshot();
                    System.out.println("[Reader] Taking Snapshot...");

                    // Sleep specifically to let the writer change state while we hold the snapshot
                    Thread.sleep(50); 

                    // Compare Live vs Snapshot
                    Point livePoint = tracker.getLocation("Truck-1");
                    Point snapPoint = snapshot.get("Truck-1");

                    System.out.println("[Reader] Comparison -> Live: " + livePoint + " | Snapshot: " + snapPoint);

                    Thread.sleep(50);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Submit tasks to execution
        executor.submit(writerTask);
        executor.submit(readerTask);

        // Shutdown mechanism
        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("Final State: " + tracker.getLocations());
    }
}

/**
 * Immutable Point class representing a location on a 2D plane.
 * Immutability is crucial here so that instances can be safely published
 * across threads without synchronization.
 */
class Point {
    public final int x;
    public final int y;

    public Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

/**
 * Thread-safe Vehicle Tracker using Delegation.
 * It delegates thread safety responsibilities to the underlying ConcurrentHashMap.
 */
class DelegatingVehicleTracker {
    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMap;

    public DelegatingVehicleTracker(Map<String, Point> points) {
        // Initialize the ConcurrentMap with the provided points
        this.locations = new ConcurrentHashMap<>(points);
        // Create a live unmodifiable view of the map
        this.unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    /**
     * Returns the live, unmodifiable view of vehicle locations.
     * Changes to the underlying map are reflected here, but the caller cannot modify it.
     */
    public Map<String, Point> getLocations() {
        return unmodifiableMap;
    }

    /**
     * Returns a static snapshot of the locations at the current moment.
     * Changes made after this call will not be reflected in this map.
     */
    public Map<String, Point> getLocationsSnapshot() {
        // Create a shallow copy of the map. Since Point is immutable, this is thread-safe.
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    /**
     * Returns the location of a specific vehicle.
     */
    public Point getLocation(String id) {
        return locations.get(id);
    }

    /**
     * Updates the location of a vehicle.
     * Uses ConcurrentMap.replace to ensure we only update if the key exists.
     */
    public void setLocation(String id, int x, int y) {
        // replace(key, value) only performs the action if the key is mapped to a value.
        // This satisfies the requirement: "only succeeds if the vehicle ID already exists".
        if (locations.replace(id, new Point(x, y)) == null) {
            // Ideally log that the vehicle ID was not found, but logic dictates strictly update only.
        }
    }
