import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ConcurrentProcessor {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        try {
            List<Element<String>> elements = new ArrayList<>();
            for (int i = 1; i <= 5; i++) {
                elements.add(new StringElement("Item " + i));
            }

            List<String> seqListResult = processElementsSequentially(elements);
            List<String> parListResult = processElementsParallel(elements, executor);

            System.out.println("Sequential List Results: " + seqListResult);
            System.out.println("Parallel List Results: " + parListResult);

            TreeNode root = new TreeNode(1);
            TreeNode child1 = new TreeNode(2);
            TreeNode child2 = new TreeNode(3);
            root.addChild(child1);
            root.addChild(child2);
            child1.addChild(new TreeNode(4));
            child1.addChild(new TreeNode(5));

            List<Integer> seqTreeResult = processTreeSequentially(root);
            List<Integer> parTreeResult = processTreeParallel(root, executor);

            System.out.println("Sequential Tree Results: " + seqTreeResult);
            System.out.println("Parallel Tree Results: " + parTreeResult);

        } finally {
            executor.shutdown();
        }
    }

    public static <T> List<T> processElementsSequentially(List<Element<T>> elements) {
        List<T> results = new ArrayList<>();
        for (Element<T> element : elements) {
            results.add(element.process());
        }
        return results;
    }

    public static <T> List<T> processElementsParallel(List<Element<T>> elements, ExecutorService executor) {
        List<Future<T>> futures = new ArrayList<>();
        for (Element<T> element : elements) {
            futures.add(executor.submit(() -> element.process()));
        }
        return collectResults(futures);
    }

    public static <T> List<T> processTreeSequentially(Node<T> root) {
        List<T> results = new ArrayList<>();
        traverseTreeSequentially(root, results);
        return results;
    }

    private static <T> void traverseTreeSequentially(Node<T> node, List<T> results) {
        if (node == null) return;
        results.add(node.compute());
        for (Node<T> child : node.getChildren()) {
            traverseTreeSequentially(child, results);
        }
    }

    public static <T> List<T> processTreeParallel(Node<T> root, ExecutorService executor) {
        List<Future<T>> futures = new ArrayList<>();
        traverseTreeParallel(root, executor, futures);
        return collectResults(futures);
    }

    private static <T> void traverseTreeParallel(Node<T> node, ExecutorService executor, List<Future<T>> futures) {
        if (node == null) return;
        futures.add(executor.submit(() -> node.compute()));
        for (Node<T> child : node.getChildren()) {
            traverseTreeParallel(child, executor, futures);
        }
    }

    private static <T> List<T> collectResults(List<Future<T>> futures) {
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }
        return results;
    }

    public interface Element<R> {
        R process();
    }

    public interface Node<R> {
        R compute();
        List<Node<R>> getChildren();
    }
}

