import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ConcurrentExecutionDemo {

    public interface Element<T> {
        T process();
    }

    public interface Node<T> {
        T compute();
        List<Node<T>> getChildren();
    }

    public static class DataProcessor<T> {
        private final ExecutorService executor;

        public DataProcessor(ExecutorService executor) {
            this.executor = executor;
        }

        public List<T> processListSequential(List<Element<T>> elements) {
            List<T> results = new ArrayList<>();
            if (elements != null) {
                for (Element<T> element : elements) {
                    results.add(element.process());
                }
            }
            return results;
        }

        public List<T> processListParallel(List<Element<T>> elements) {
            List<T> results = new ArrayList<>();
            if (elements != null && !elements.isEmpty()) {
                List<Callable<T>> tasks = new ArrayList<>();
                for (Element<T> element : elements) {
                    tasks.add(() -> element.process());
                }
                try {
                    List<Future<T>> futures = executor.invokeAll(tasks);
                    for (Future<T> future : futures) {
                        results.add(future.get());
                    }
                } catch (InterruptedException | ExecutionException e) {
                    e.printStackTrace();
                }
            }
            return results;
        }

        public List<T> processTreeSequential(Node<T> root) {
            List<T> results = new ArrayList<>();
            processNodeSequential(root, results);
            return results;
        }

        private void processNodeSequential(Node<T> node, List<T> results) {
            if (node != null) {
                results.add(node.compute());
                List<Node<T>> children = node.getChildren();
                if (children != null) {
                    for (Node<T> child : children) {
                        processNodeSequential(child, results);
                    }
                }
            }
        }

        public List<T> processTreeParallel(Node<T> root) {
            List<T> results = Collections.synchronizedList(new ArrayList<>());
            List<Future<?>> pendingTasks = new ArrayList<>();

            processNodeParallelRecursively(root, results, pendingTasks);

            for (Future<?> future : pendingTasks) {
                try {
                    future.get();
                } catch (InterruptedException | ExecutionException e) {
                    e.printStackTrace();
                }
            }
            return results;
        }

        private void processNodeParallelRecursively(Node<T> node, List<T> results, List<Future<?>> pendingTasks) {
            if (node != null) {
                Future<?> future = executor.submit(() -> {
                    results.add(node.compute());
                });
                pendingTasks.add(future);

                List<Node<T>> children = node.getChildren();
                if (children != null) {
                    for (Node<T> child : children) {
                        processNodeParallelRecursively(child, results, pendingTasks);
                    }
                }
            }
        }
    }

    static class SimpleElement implements Element<String> {
        private final String name;

        public SimpleElement(String name) {
            this.name = name;
        }

        public String process() {
            return "Processed: " + name + " [" + Thread.currentThread().getName() + "]";
        }
    }

    static class SimpleNode implements Node<String> {
        private final String value;
        private final List<Node<String>> children;

        public SimpleNode(String value) {
            this.value = value;
            this.children = new ArrayList<>();
        }

        public void addChild(SimpleNode child) {
            this.children.add(child);
        }

        public String compute() {
            return "Computed: " + value + " [" + Thread.currentThread().getName() + "]";
        }

        public List<Node<String>> getChildren() {
            return children;
