import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ThreeStooges {

    private final List<String> stoogeList;
    private final Set<String> stoogeSet;

    public ThreeStooges() {
        List<String> names = Arrays.asList("Moe", "Larry", "Curly");
        this.stoogeList = Collections.unmodifiableList(names);
        this.stoogeSet = Collections.unmodifiableSet(new HashSet<>(names));
    }

    public boolean isStooge(String name) {
        return stoogeSet.contains(name);
    }

    public String getStoogeNames() {
        return stoogeList.toString();
    }

    public static void main(String[] args) {
        ThreeStooges stooges = new ThreeStooges();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            String[] namesToCheck = {"Moe", "Shemp", "Larry", "Joe", "Curly"};
            for (String name : namesToCheck) {
                System.out.println("Is " + name + " a Stooge? " + stooges.isStooge(name));
            }
        });

        executor.submit(() -> {
            System.out.println("All Stooges: " + stooges.getStoogeNames());
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

