import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StripedMap {

    private static final int N_LOCKS = 16;
    private final Node[] buckets;
    private final Object[] locks;

    public StripedMap(int numBuckets) {
        buckets = new Node[numBuckets];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private static class Node {
        final Object key;
        Object value;
        Node next;

        Node(Object key, Object value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private int getHashIndex(Object key) {
        return Math.abs(key.hashCode() % buckets.length);
    }

    public Object get(Object key) {
        int index = getHashIndex(key);
        synchronized (locks[index % N_LOCKS]) {
            Node current = buckets[index];
            while (current != null) {
                if (current.key.equals(key)) {
                    return current.value;
                }
                current = current.next;
            }
            return null;
        }
    }

    public void put(Object key, Object value) {
        int index = getHashIndex(key);
        synchronized (locks[index % N_LOCKS]) {
            Node current = buckets[index];
            while (current != null) {
                if (current.key.equals(key)) {
                    current.value = value;
                    return;
                }
                current = current.next;
            }
            buckets[index] = new Node(key, value, buckets[index]);
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                buckets[i] = null;
            }
        }
    }

    public static void main(String[] args) {
        StripedMap map = new StripedMap(64);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        executor.execute(() -> {
            for (int i = 0; i < 1000; i++) {
                map.put("Key" + i, "Value" + i);
            }
            System.out.println("Thread 1 finished putting.");
        });

        executor.execute(() -> {
            for (int i = 1000; i < 2000; i++) {
                map.put("Key" + i, "Value" + i);
            }
            System.out.println("Thread 2 finished putting.");
        });

        executor.execute(() -> {
            try {
                Thread.sleep(50);
                int count = 0;
                for (int i = 0; i < 2000; i++) {
                    if (map.get("Key" + i) != null) {
                        count++;
                    }
                }
                System.out.println("Thread 3 found " + count + " items.");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.execute(() -> {
            try {
                Thread.sleep(150);
                map.clear();
                System.out.println("Thread 4 cleared the map.");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(2, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        System.out.println("Execution finished.");
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StripedMap<K, V> {

    private static final int N_LOCKS = 16;
    private final Node<K, V>[] buckets;
    private final Object[] locks;

    static class Node<K, V> {
        final K key;
        volatile V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    public StripedMap(int numBuckets) {
        buckets = (Node<K, V>[]) new Node[numBuckets];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int getBucketIndex(Object key) {
        return (key.hashCode() & 0x7FFFFFFF) % buckets.length;
    }

    public V get(Object key) {
        int bucketIndex = getBucketIndex(key);
        synchronized (locks[bucketIndex % N_LOCKS]) {
            for (Node<K, V> node = buckets[bucketIndex]; node != null; node = node.next) {
                if (node.key.equals(key)) {
                    return node.value;
                }
            }
            return null;
        }
    }

    public void put(K key, V value) {
        int bucketIndex = getBucketIndex(key);
        synchronized (locks[bucketIndex % N_LOCKS]) {
            for (Node<K, V> node = buckets[bucketIndex]; node != null; node = node.next) {
                if (node.key.equals(key)) {
                    node.value = value;
                    return;
                }
            }
            buckets[bucketIndex] = new Node<>(key, value, buckets[bucketIndex]);
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                buckets[i] = null;
            }
        }
    }

    public int size() {
        int count = 0;
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                for (Node<K, V> node = buckets[i]; node != null; node = node.next) {
                    count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        final int THREAD_COUNT = 4;
        final int ITEMS_PER_THREAD = 1000;
        StripedMap<String, Integer> map = new StripedMap<>(128);
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);

        for (int i = 0; i < THREAD_COUNT; i++) {
            final int threadIndex = i;
            executor.submit(() -> {
                for (int j = 0; j < ITEMS_PER_THREAD; j++) {
                    String key = "Key-" + threadIndex + "-" + j;
                    map.put(key, j);
                    map.get(key); 
                }
            });
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        int expectedSize = THREAD_COUNT * ITEMS_PER_THREAD;
        int actualSize = map.size();

        System.out.println("Map size after insertions: " + actualSize);
        if (actualSize == expectedSize) {
            System.out.println("Success: Size matches expected value.");
        } else {
            System.out.println("Error: Size mismatch.");
        }

        map.clear();
        System.out.println("Map size after clear: " + map.size());
    }
}

