import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StripedMap<K, V> {

    private static final int N_LOCKS = 16;
    private final Node<K, V>[] buckets;
    private final Object[] locks;

    static class Node<K, V> {
        final K key;
        volatile V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    public StripedMap(int numBuckets) {
        buckets = (Node<K, V>[]) new Node[numBuckets];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int getBucketIndex(Object key) {
        return (key.hashCode() & 0x7FFFFFFF) % buckets.length;
    }

    public V get(Object key) {
        int bucketIndex = getBucketIndex(key);
        synchronized (locks[bucketIndex % N_LOCKS]) {
            for (Node<K, V> node = buckets[bucketIndex]; node != null; node = node.next) {
                if (node.key.equals(key)) {
                    return node.value;
                }
            }
            return null;
        }
    }

    public void put(K key, V value) {
        int bucketIndex = getBucketIndex(key);
        synchronized (locks[bucketIndex % N_LOCKS]) {
            for (Node<K, V> node = buckets[bucketIndex]; node != null; node = node.next) {
                if (node.key.equals(key)) {
                    node.value = value;
                    return;
                }
            }
            buckets[bucketIndex] = new Node<>(key, value, buckets[bucketIndex]);
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                buckets[i] = null;
            }
        }
    }

    public int size() {
        int count = 0;
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                for (Node<K, V> node = buckets[i]; node != null; node = node.next) {
                    count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        final int THREAD_COUNT = 4;
        final int ITEMS_PER_THREAD = 1000;
        StripedMap<String, Integer> map = new StripedMap<>(128);
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);

        for (int i = 0; i < THREAD_COUNT; i++) {
            final int threadIndex = i;
            executor.submit(() -> {
                for (int j = 0; j < ITEMS_PER_THREAD; j++) {
                    String key = "Key-" + threadIndex + "-" + j;
                    map.put(key, j);
                    map.get(key); 
                }
            });
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        int expectedSize = THREAD_COUNT * ITEMS_PER_THREAD;
        int actualSize = map.size();

        System.out.println("Map size after insertions: " + actualSize);
        if (actualSize == expectedSize) {
            System.out.println("Success: Size matches expected value.");
        } else {
            System.out.println("Error: Size mismatch.");
        }

        map.clear();
        System.out.println("Map size after clear: " + map.size());
    }
}
