import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ConcurrentMoneyTransfer {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Account accountA = new Account("Account A", new DollarAmount(1000));
        Account accountB = new Account("Account B", new DollarAmount(1000));

        Runnable task1 = () -> {
            try {
                boolean success = transfer(accountA, accountB, new DollarAmount(500), 1000, TimeUnit.MILLISECONDS);
                System.out.println(Thread.currentThread().getName() + " transfer A->B success: " + success + 
                                   ", A Balance: " + accountA.getBalance() + ", B Balance: " + accountB.getBalance());
            } catch (InsufficientFundsException | InterruptedException e) {
                System.out.println(Thread.currentThread().getName() + " transfer A->B failed: " + e.getClass().getSimpleName());
            }
        };

        Runnable task2 = () -> {
            try {
                boolean success = transfer(accountB, accountA, new DollarAmount(300), 1000, TimeUnit.MILLISECONDS);
                System.out.println(Thread.currentThread().getName() + " transfer B->A success: " + success +
                                   ", B Balance: " + accountB.getBalance() + ", A Balance: " + accountA.getBalance());
            } catch (InsufficientFundsException | InterruptedException e) {
                System.out.println(Thread.currentThread().getName() + " transfer B->A failed: " + e.getClass().getSimpleName());
            }
        };

        executor.submit(task1);
        executor.submit(task2);

        executor.shutdown();
        try {
            executor.awaitTermination(2, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static boolean transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit)
            throws InsufficientFundsException, InterruptedException {

        long nanosTimeout = unit.toNanos(timeout);
        long stopTime = System.nanoTime() + nanosTimeout;

        while (System.nanoTime() < stopTime) {
            long remaining = stopTime - System.nanoTime();
            if (remaining <= 0) return false;

            // Attempt to acquire locks with a short timeout to allow for backoff strategy
            // We use a small slice of time (e.g., 10ms) or the remaining time, whichever is smaller
            long tryLockTime = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(10));

            if (source.getLock().tryLock(tryLockTime, TimeUnit.NANOSECONDS)) {
                try {
                    remaining = stopTime - System.nanoTime();
                    if (remaining <= 0) return false;

                    tryLockTime = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(10));

                    if (destination.getLock().tryLock(tryLockTime, TimeUnit.NANOSECONDS)) {
                        try {
                            if (source.getBalance().compareTo(amount) < 0) {
                                throw new InsufficientFundsException();
                            }
                            source.debit(amount);
                            destination.credit(amount);
                            return true;
                        } finally {
                            destination.getLock().unlock();
                        }
                    }
                } finally {
                    source.getLock().unlock();
                }
            }

            // Backoff strategy
            remaining = stopTime - System.nanoTime();
            if (remaining > 0) {
                long delay = getFixedDelayComponent() + getRandomDelayComponent();
                TimeUnit.NANOSECONDS.sleep(Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(delay)));
            }
        }
        return false;
    }

    private static long getFixedDelayComponent() {
        return 10; // 10 milliseconds fixed delay
    }

    private static long getRandomDelayComponent() {
        return ThreadLocalRandom.current().nextLong(0, 50); // 0-50 milliseconds random delay
    }

    // Nested Classes

    static class DollarAmount implements Comparable<DollarAmount> {
        private final int cents;

        public DollarAmount(int cents) {
            this.cents = cents;
        }

        public DollarAmount add(DollarAmount other) {
            return new DollarAmount(this.cents + other.cents);
        }

        public DollarAmount subtract(DollarAmount other) {
            return new DollarAmount(this.cents - other.cents);
        }

        @Override
        public int compareTo(DollarAmount other) {
            return Integer.compare(this.cents, other.cents);
        }

        @Override
        public String toString() {
            return "$" + (cents / 100.0);
        }
    }

    static class Account {
        private final String name;
        private DollarAmount balance;
        private final ReentrantLock lock = new ReentrantLock();

        public Account(String name, DollarAmount balance) {
            this.name = name;
            this.balance = balance;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public DollarAmount getBalance() {
            return balance;
        }

        public void debit(DollarAmount amount) {
            this.balance = this.balance.subtract(amount);
        }

        public void credit(DollarAmount amount) {
            this.balance = this.balance.add(amount);
        }
    }

    static class InsufficientFundsException extends Exception {
        public InsufficientFundsException() {
            super("Insufficient funds for transfer");
        }
    }
}
