        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public static void main(String[] args) {
        // Create the wrapper around a standard HashMap
        ReadWriteMap<String, Integer> concurrentMap = new ReadWriteMap<>(new HashMap<>());

        // Create a fixed thread pool with 3 threads. 
        // Total threads = 1 (Main) + 3 (Pool) = 4, satisfying the limit.
        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Task 1: Writer - Populates the map
        executor.submit(() -> {
            System.out.println("Writer thread started.");
            for (int i = 0; i < 10; i++) {
                concurrentMap.put("Key" + i, i);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("Writer thread finished.");
        });

        // Task 2: Reader - Reads from the map
        executor.submit(() -> {
            System.out.println("Reader thread started.");
            for (int i = 0; i < 10; i++) {
                Integer value = concurrentMap.get("Key" + i);
                System.out.println("Read: Key" + i + " = " + value);
