                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("Reader thread finished.");
        });

        // Task 3: Modifier - Removes elements
        executor.submit(() -> {
            try {
                // Wait for some data to be written
                Thread.sleep(300);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println("Remover thread started.");
            if (concurrentMap.containsKey("Key0")) {
                concurrentMap.remove("Key0");
                System.out.println("Remover deleted Key0");
            }
            System.out.println("Remover thread finished.");
        });

        // Shutdown executor and wait for tasks to complete
        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

