        try {
            return map.remove(key);
        } finally {
            writeLock.unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        writeLock.lock();
        try {
            map.putAll(m);
        } finally {
            writeLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            map.clear();
        } finally {
            writeLock.unlock();
        }
    }

    public V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public static void main(String[] args) {
        // Create the wrapper around a standard HashMap
        ReadWriteMap<String, Integer> concurrentMap = new ReadWriteMap<>(new HashMap<>());

        // Create a fixed thread pool with 3 threads. 
        // Total threads = 1 (Main) + 3 (Pool) = 4, satisfying the limit.
        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Task 1: Writer - Populates the map
        executor.submit(() -> {
            System.out.println("Writer thread started.");
            for (int i = 0; i < 10; i++) {
                concurrentMap.put("Key" + i, i);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("Writer thread finished.");
        });

        // Task 2: Reader - Reads from the map
        executor.submit(() -> {
            System.out.println("Reader thread started.");
            for (int i = 0; i < 10; i++) {
                Integer value = concurrentMap.get("Key" + i);
                System.out.println("Read: Key" + i + " = " + value);
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("Reader thread finished.");
        });

        // Task 3: Modifier - Removes elements
        executor.submit(() -> {
            try {
                // Wait for some data to be written
                Thread.sleep(300);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println("Remover thread started.");
            if (concurrentMap.containsKey("Key0")) {
                concurrentMap.remove("Key0");
                System.out.println("Remover deleted Key0");
            }
            System.out.println("Remover thread finished.");
        });

        // Shutdown executor and wait for tasks to complete
        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
