import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class BetterAttributeStore {

    private final Map<String, String> attributes = new HashMap<>();

    public void setAttribute(String name, String location) {
        synchronized (this) {
            attributes.put("users." + name + ".location", location);
        }
    }

    public boolean userLocationMatches(String name, String regexp) {
        String key = "users." + name + ".location";
        String value;
        synchronized (this) {
            value = attributes.get(key);
        }
        if (value == null) {
            return false;
        }
        return Pattern.matches(regexp, value);
    }

    public static void main(String[] args) {
        BetterAttributeStore store = new BetterAttributeStore();

        store.setAttribute("Alice", "New York");
        store.setAttribute("Bob", "London");
        store.setAttribute("Charlie", "Paris");

        ExecutorService executor = Executors.newFixedThreadPool(4);

        executor.execute(() -> {
            boolean match = store.userLocationMatches("Alice", "New.*");
            System.out.println("Alice matches 'New.*': " + match);
        });

        executor.execute(() -> {
            boolean match = store.userLocationMatches("Bob", "Lon.on");
            System.out.println("Bob matches 'Lon.on': " + match);
        });

        executor.execute(() -> {
            boolean match = store.userLocationMatches("Charlie", "Berlin");
            System.out.println("Charlie matches 'Berlin': " + match);
        });

        executor.execute(() -> {
            store.setAttribute("David", "Tokyo");
            boolean match = store.userLocationMatches("David", "Tok.o");
            System.out.println("David matches 'Tok.o': " + match);
        });

        executor.execute(() -> {
            boolean match = store.userLocationMatches("Eve", ".*");
            System.out.println("Eve matches '.*': " + match);
        });

        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

