import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ConcurrentBarrierTimerApp {

    public static void main(String[] args) {
        BarrierTimer timer = new BarrierTimer();

        // Constraint: Total threads including main must not exceed 3.
        // We use a fixed thread pool of 2 threads.
        int threadCount = 2;
        ExecutorService executor = Executors.newFixedThreadPool(threadCount);

        // CyclicBarrier triggers the BarrierTimer's run method when all threads trip the barrier
        CyclicBarrier barrier = new CyclicBarrier(threadCount, timer);

        Runnable workerTask = () -> {
            try {
                // First synchronization: all threads arrive, timer starts (run() called first time)
                barrier.await();

                // Simulate concurrent work
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                // Second synchronization: all threads arrive, timer ends (run() called second time)
                barrier.await();
            } catch (InterruptedException | BrokenBarrierException e) {
                e.printStackTrace();
            }
        };

        // Submit worker tasks
        for (int i = 0; i < threadCount; i++) {
            executor.submit(workerTask);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(2, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Elapsed time (ns): " + timer.getTime());

        timer.clear();
    }
}

